import * as crypto from "node:crypto"
import type { Credentials, ToolDefinition } from "./types.js"

const SHA3_WASM_B64 = "";

export type ParseEvent =
  | { type: "text_delta"; content: string }
  | { type: "thinking_delta"; content: string }
  | { type: "tool_call_delta"; id: string; name: string; argsDelta: string }
  | { type: "tool_call_start"; id: string; name: string }
  | { type: "tool_call_end"; id: string; name: string; arguments: Record<string, unknown> }
  | { type: "message_id"; id: number }
  | { type: "title"; title: string }
  | { type: "error"; message: string }
  | { type: "end" }
  | { type: "clear_response" }

function extractChallenge(obj: any): any {
  if (!obj || typeof obj !== "object") return null
  if (obj.challenge && typeof obj.challenge === "object") return obj.challenge
  for (const key of Object.keys(obj)) {
    const found = extractChallenge(obj[key])
    if (found) return found
  }
  return null
}

const JUNK_TOKENS = [
  " response",
  "<|end▁of▁thinking|>",
  "<｜end_of_thinking｜>",
  "<|end_of_thinking|>",
  "<|endoftext|>",
  "FINISHED",
]

export class PowSolver {
  async solve(challenge: any): Promise<number> {
    if (challenge.algorithm === "sha256") {
      return this.solveSha256(challenge)
    }
    if (challenge.algorithm === "DeepSeekHashV1") {
      return this.solveDeepSeekHash(challenge)
    }
    throw new Error(`Unsupported algorithm: ${challenge.algorithm}`)
  }

  private solveSha256(challenge: any): number {
    const { challenge: target, salt, difficulty } = challenge
    let nonce = 0
    while (true) {
      const hash = crypto
        .createHash("sha256")
        .update(salt + target + nonce)
        .digest("hex")
      let zeroBits = 0
      for (const ch of hash) {
        const val = parseInt(ch, 16)
        if (val === 0) zeroBits += 4
        else {
          zeroBits += Math.clz32(val) - 28
          break
        }
      }
      const targetDiff = difficulty > 1000 ? Math.floor(Math.log2(difficulty)) : difficulty
      if (zeroBits >= targetDiff) return nonce
      if (++nonce > 1_000_000) throw new Error("SHA256 PoW timeout")
    }
  }

    private async solveDeepSeekHash(challenge: any): Promise<number> {
    const wasmBuffer = Buffer.from(SHA3_WASM_B64, "base64");
    const { instance } = await WebAssembly.instantiate(wasmBuffer, { wbg: {} });
    const exports = instance.exports as any;
    const memory = exports.memory;
    const alloc = exports.__wbindgen_export_0;
    const addStack = exports.__wbindgen_add_to_stack_pointer;
    const wasmSolve = exports.wasm_solve;

    const encode = (str: string): [number, number] => {
      const buf = Buffer.from(str, "utf8");
      const ptr = alloc(buf.length, 1);
      new Uint8Array(memory.buffer).set(buf, ptr);
      return [ptr, buf.length];
    };

    const prefix = `${challenge.salt}_${challenge.expire_at}_`;
    const [ptrC, lenC] = encode(challenge.challenge);
    const [ptrP, lenP] = encode(prefix);
    const retptr = addStack(-16);
    wasmSolve(retptr, ptrC, lenC, ptrP, lenP, challenge.difficulty);
    addStack(16);

    const view = new DataView(memory.buffer);
    const status = view.getInt32(retptr, true);
    if (status === 0) throw new Error("DeepSeekHashV1 solve failed");
    return view.getFloat64(retptr + 8, true);
  }
}

export class DeepSeekClient {
  private powSolver = new PowSolver()
  private csrfToken = ""
  private preferredModel: string

  constructor(
    private creds: Credentials,
    preferredModel?: string,
  ) {
    this.preferredModel = preferredModel || "deepseek_pro"
  }

  private async headers(): Promise<Record<string, string>> {
    return {
      Cookie: this.creds.cookie,
      "User-Agent": this.creds.userAgent,
      "Content-Type": "application/json",
      Accept: "*/*",
      Authorization: `Bearer ${this.creds.bearer}`,
      Referer: "https://chat.deepseek.com/",
      Origin: "https://chat.deepseek.com",
      "x-client-platform": "web",
      "x-client-version": "2.0.0",
      "x-app-version": "2.0.0",
      "x-client-locale": "zh_CN",
      "x-client-timezone-offset": "28800",
    }
  }

  async createChatSession(): Promise<string> {
    const targetPath = "/api/v0/chat_session/create"
    const res = await fetch(`https://chat.deepseek.com${targetPath}`, {
      method: "POST",
      headers: await this.headers(),
      body: JSON.stringify({}),
    })
    if (!res.ok) {
      const text = await res.text()
      throw new Error(`Failed to create chat session (${res.status}): ${text}`)
    }
    const data: any = await res.json()
    const sessionId =
      data?.data?.biz_data?.chat_session?.id ||
      data?.data?.biz_data?.id ||
      data?.data?.biz_data?.chat_session_id ||
      data?.biz_data?.chat_session?.id ||
      data?.biz_data?.id ||
      data?.biz_data?.chat_session_id ||
      ""
    if (!sessionId) throw new Error("Empty chat session ID")
    return sessionId
  }

  async deleteSession(sessionId: string): Promise<void> {
    const res = await fetch("https://chat.deepseek.com/api/v0/chat_session/delete", {
      method: "POST", headers: await this.headers(),
      body: JSON.stringify({ chat_session_id: sessionId }),
    })
    if (!res.ok) throw new Error(`delete session failed (${res.status})`)
  }

  private async createPowChallenge(targetPath: string) {
    const res = await fetch(
      "https://chat.deepseek.com/api/v0/chat/create_pow_challenge",
      {
        method: "POST",
        headers: await this.headers(),
        body: JSON.stringify({ target_path: targetPath }),
      }
    )
    if (!res.ok) throw new Error(`PoW challenge failed (${res.status})`)
    const data: any = await res.json()
    const challenge =
      data?.data?.biz_data?.challenge ||
      data?.data?.challenge ||
      data?.challenge ||
      extractChallenge(data)
    if (!challenge) throw new Error("PoW challenge missing")
    return challenge
  }

  async chat(
    sessionId: string,
    parentMessageId: number | null,
    message: string,
    thinkingEnabled: boolean,
    searchEnabled: boolean,
    modelType: string,
    refFileIds: string[] = [],
    signal?: AbortSignal,
    tools?: ToolDefinition[],
  ): Promise<ReadableStream<Uint8Array>> {
    const targetPath = "/api/v0/chat/completion"
    const challenge = await this.createPowChallenge(targetPath)
    const answer = await this.powSolver.solve(challenge)
    const powResponse = Buffer.from(
      JSON.stringify({ ...challenge, answer, target_path: targetPath })
    ).toString("base64")

    const bodyObj: Record<string, unknown> = {
      chat_session_id: sessionId,
      parent_message_id: parentMessageId ?? null,
      prompt: message,
      ref_file_ids: refFileIds,
      thinking_enabled: thinkingEnabled,
      search_enabled: searchEnabled,
      model_type: modelType,
      preempt: false,
    }

    if (tools && tools.length > 0) {
      bodyObj.tools = tools
    }

    const res = await fetch(`https://chat.deepseek.com${targetPath}`, {
      method: "POST",
      headers: {
        ...(await this.headers()),
        "x-ds-pow-response": powResponse,
      },
      body: JSON.stringify(bodyObj),
      signal,
    })

    if (!res.ok) {
      const text = await res.text()
      throw new Error(
        `DeepSeek chat failed (${res.status}): ${text.slice(0, 200)}`
      )
    }
    return res.body!
  }

  async uploadFile(
    filePath: string,
    modelType: string,
  ): Promise<{ fileId: string; filename: string }> {
    const fs = await import("node:fs")
    const path = await import("node:path")
    const data = fs.readFileSync(filePath)
    const filename = path.basename(filePath)

    const targetPath = "/api/v0/file/upload_file"
    const challenge = await this.createPowChallenge(targetPath)
    const answer = await this.powSolver.solve(challenge)
    const powResponse = Buffer.from(
      JSON.stringify({ ...challenge, answer, target_path: targetPath })
    ).toString("base64")

    const boundary =
      "----Ds2apiUpload" + crypto.randomBytes(16).toString("hex")
    const header = `------${boundary}\r\nContent-Disposition: form-data; name="file"; filename="${filename}"\r\nContent-Type: application/octet-stream\r\n\r\n`
    const footer = `\r\n------${boundary}--\r\n`
    const body = Buffer.concat([
      Buffer.from(header, "utf-8"),
      data,
      Buffer.from(footer, "utf-8"),
    ])

    const res = await fetch(
      "https://chat.deepseek.com/api/v0/file/upload_file",
      {
        method: "POST",
        headers: {
          ...(await this.headers()),
          "Content-Type": `multipart/form-data; boundary=----${boundary}`,
          "x-ds-pow-response": powResponse,
          "x-file-size": String(data.length),
          "x-thinking-enabled": "1",
          "x-model-type": modelType,
        },
        body,
      }
    )

    if (!res.ok) {
      const text = await res.text()
      throw new Error(`文件上传失败 (${res.status}): ${text.slice(0, 200)}`)
    }

    const json: any = await res.json()
    const fileId =
      json?.data?.biz_data?.id ||
      json?.data?.biz_data?.file_id ||
      json?.data?.id ||
      json?.data?.file_id ||
      ""
    if (!fileId) throw new Error("上传响应中未找到 file_id")

    return { fileId, filename }
  }

  private async fetchFileStatus(
    fileId: string,
  ): Promise<{ status: string } | null> {
    const url = `https://chat.deepseek.com/api/v0/file/fetch_files?file_ids=${encodeURIComponent(fileId)}`
    const res = await fetch(url, {
      method: "GET",
      headers: await this.headers(),
    })
    if (!res.ok) return null
    const json: any = await res.json()
    const walk = (obj: any): any | null => {
      if (!obj || typeof obj !== "object") return null
      if (Array.isArray(obj)) {
        for (const item of obj) {
          const found = walk(item)
          if (found) return found
        }
        return null
      }
      const id = obj.id || obj.file_id || ""
      if (id === fileId) {
        return { status: obj.status || obj.file_status || "uploaded" }
      }
      for (const v of Object.values(obj)) {
        const found = walk(v)
        if (found) return found
      }
      return null
    }
    return walk(json)
  }

  async waitForUploadedFile(
    fileId: string,
    maxAttempts = 60,
  ): Promise<void> {
    const readyStatuses = [
      "processed",
      "ready",
      "done",
      "available",
      "success",
      "completed",
      "finished",
    ]
    for (let i = 0; i < maxAttempts; i++) {
      const file = await this.fetchFileStatus(fileId)
      if (file && readyStatuses.includes(file.status.toLowerCase())) return
      await new Promise((r) => setTimeout(r, 1000))
    }
  }
}

export class StreamParser {
  private tagBuffer = ""
  private currentMode: "text" | "thinking" | "tool_call" = "text"
  private currentToolName = ""
  private currentToolId = ""
  private currentToolArgs = ""
  private currentEventType = ""
  private events: ParseEvent[] = []
  private citationLinks: Map<number, string> = new Map()
  private currentFragmentType: string | null = null

  private emitText(content: string) {
    if (content) this.events.push({ type: "text_delta", content })
  }

  private emitThinking(content: string) {
    if (content) this.events.push({ type: "thinking_delta", content })
  }

  private emitToolCallDelta(argsDelta: string) {
    if (argsDelta) {
      this.events.push({
        type: "tool_call_delta",
        id: this.currentToolId,
        name: this.currentToolName,
        argsDelta,
      })
    }
  }

  private parseToolArgs(raw: string): Record<string, unknown> {
    try {
      return JSON.parse(raw.trim())
    } catch {
      return {}
    }
  }

  async *parse(
    stream: ReadableStream<Uint8Array>,
  ): AsyncGenerator<ParseEvent> {
    const reader = stream.getReader()
    const decoder = new TextDecoder()
    let lineBuffer = ""

    try {
      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        lineBuffer += decoder.decode(value, { stream: true })
        const lines = lineBuffer.split("\n")
        lineBuffer = lines.pop()!
        for (const line of lines) {
          const trimmed = line.trim()
          if (!trimmed) continue
          this.feedLine(trimmed)
        }
        yield* this.flushEvents()
      }
      if (lineBuffer.trim()) {
        this.feedLine(lineBuffer.trim())
        yield* this.flushEvents()
      }
    } catch (err: any) {
      if (err.name === "AbortError") {
        this.events.push({ type: "error", message: "请求已取消" })
        yield* this.flushEvents()
        return
      }
      throw err
    } finally {
      reader.releaseLock()
    }

    this.feedLine("")
    this.flush()
    yield* this.flushEvents()
  }

  private feedLine(line: string) {
    if (line.startsWith("event: ")) {
      this.currentEventType = line.slice(7).trim()
      return
    }

    if (!line.startsWith("data: ")) return
    const jsonStr = line.slice(6)

    try {
      const data = JSON.parse(jsonStr)
      this.processData(data)
    } catch {}
  }

  private processData(data: any) {
    this.collectCitations(data)

    if (data.response_message_id !== undefined) {
      this.events.push({
        type: "message_id",
        id: data.response_message_id,
      })
    } else if (data.v?.response?.message_id !== undefined) {
      this.events.push({
        type: "message_id",
        id: data.v.response.message_id,
      })
    }

    if (this.currentEventType === "title" && data.content) {
      this.events.push({ type: "title", title: data.content })
      this.currentEventType = ""
      return
    }

    if (this.currentEventType === "hint") {
      if (data.type === "error") {
        const msg = typeof data.content === "string" ? data.content : ""
        if (msg) this.events.push({ type: "error", message: msg })
      }
      if (data.clear_response) {
        this.events.push({ type: "clear_response" })
      }
      this.currentEventType = ""
      return
    }

    this.currentEventType = ""

    let content = ""
    if (typeof data.v === "string") {
      content = data.v
    } else if (typeof data.content === "string") {
      content = data.content
    } else if (data.v?.content && typeof data.v.content === "string") {
      content = data.v.content
    } else if (data.v?.response?.fragments) {
      const frags = data.v.response.fragments
      for (const frag of frags) {
        this.currentFragmentType = frag.type
        if (frag.content) {
          const isThinking =
            frag.type === "THINK" || data.p?.includes("reasoning")
          this.pushDelta(frag.content, isThinking ? "thinking" : undefined)
        }
      }
      return
    }

    if (data.p === "response/fragments" && Array.isArray(data.v)) {
      for (const frag of data.v) {
        this.currentFragmentType = frag.type
        if (frag.content) {
          const isThinking = frag.type === "THINK"
          this.pushDelta(frag.content, isThinking ? "thinking" : undefined)
        }
      }
      return
    }

    if (!content) return

    if (content === "FINISHED" && this.currentMode === "tool_call") {
      let args: Record<string, unknown> = {}
      try {
        args = this.parseToolArgs(this.currentToolArgs)
      } catch {}
      this.events.push({
        type: "tool_call_end",
        id: this.currentToolId,
        name: this.currentToolName,
        arguments: args,
      })
      this.currentMode = "text"
      this.currentToolArgs = ""
      return
    }
    if (content === "FINISHED") return

    if (
      data.p?.includes("reasoning") ||
      data.type === "thinking" ||
      this.currentFragmentType === "THINK"
    ) {
      this.pushDelta(content, "thinking")
    } else {
      this.pushDelta(content)
    }
  }

  private pushDelta(delta: string, forceType?: "text" | "thinking") {
    if (!delta) return

    if (JUNK_TOKENS.includes(delta)) {
      return
    }

    if (forceType === "thinking") {
      this.emitThinking(delta)
      return
    }

    this.tagBuffer += delta
    this.checkTags()
  }

  private collectCitations(obj: any, seen?: WeakSet<object>): void {
    if (!obj || typeof obj !== "object") return
    const visited = seen ?? new WeakSet<object>()
    if (visited.has(obj as object)) return
    visited.add(obj as object)
    if (
      obj.url &&
      typeof obj.url === "string" &&
      obj.url.startsWith("http")
    ) {
      const idx = obj.cite_index ?? obj.index
      if (typeof idx === "number") this.citationLinks.set(idx, obj.url)
    }
    for (const v of Object.values(obj)) {
      if (v && typeof v === "object") this.collectCitations(v, visited)
    }
  }

  getCitationLinks(): Map<number, string> {
    return this.citationLinks
  }

  private checkTags() {
    while (this.tagBuffer) {
      const thinkStartMatch = this.tagBuffer.match(
        /<(?:think(?:ing)?|thought)\b[^<>]*>/i,
      )
      const thinkEndMatch = this.tagBuffer.match(
        /<\/(?:think(?:ing)?|thought)\b[^<>]*>/i,
      )
      const toolCallStartMatch =
        this.tagBuffer.match(
          /<\|DSML\|invoke\s+name=['"]?([^'">]+)['"]?[^>]*>/i,
        ) ||
        this.tagBuffer.match(
          /<tool_call\s+(?:id=['"]?([^'"]+)['"]?\s+)?name=['"]?([^'"]+)['"]?(?:\s+id=['"]?([^'"]+)['"]?)?\s*>/i,
        ) ||
        this.tagBuffer.match(
          /<tool_call\s+id=['"]?([^'"]+)['"]?\s*>/i,
        )
      const dsmlContainerStart = this.tagBuffer.match(
        /<\|DSML\|tool_?calls\b[^<>]*>/i,
      )
      const toolCallEndMatch =
        this.tagBuffer.match(/<\/\|DSML\|invoke\b[^<>]*>/i) ||
        this.tagBuffer.match(/<\/\|DSML\|tool_?calls\b[^<>]*>/i) ||
        this.tagBuffer.match(/<\|DSML\|invoke\s*\/>/i) ||
        this.tagBuffer.match(/<\/tool_call\b[^<>]*>/i)
      const finalStartMatch = this.tagBuffer.match(
        /<final\b[^<>]*>/i,
      )
      const finalEndMatch = this.tagBuffer.match(
        /<\/final\b[^<>]*>/i,
      )
      const replyMatch = this.tagBuffer.match(
        /\[\[reply_to_current\]\]/i,
      )
      const malformedThinkMatch = this.tagBuffer.match(
        /\n?think\s*>/i,
      )

      const indices: {
        type: string
        idx: number
        len: number
        id?: string | null
        name?: string
      }[] = [
        {
          type: "think_start",
          idx: thinkStartMatch ? thinkStartMatch.index! : -1,
          len: thinkStartMatch ? thinkStartMatch[0].length : 0,
        },
        {
          type: "think_end",
          idx: thinkEndMatch ? thinkEndMatch.index! : -1,
          len: thinkEndMatch ? thinkEndMatch[0].length : 0,
        },
        {
          type: "final_start",
          idx: finalStartMatch ? finalStartMatch.index! : -1,
          len: finalStartMatch ? finalStartMatch[0].length : 0,
        },
        {
          type: "final_end",
          idx: finalEndMatch ? finalEndMatch.index! : -1,
          len: finalEndMatch ? finalEndMatch[0].length : 0,
        },
        {
          type: "tool_call_start",
          idx: toolCallStartMatch ? toolCallStartMatch.index! : -1,
          len: toolCallStartMatch ? toolCallStartMatch[0].length : 0,
          id: toolCallStartMatch
            ? toolCallStartMatch[3] || toolCallStartMatch[1]
            : null,
          name: toolCallStartMatch
            ? toolCallStartMatch[2] || toolCallStartMatch[1] || ""
            : "",
        },
        {
          type: "tool_call_end",
          idx: toolCallEndMatch ? toolCallEndMatch.index! : -1,
          len: toolCallEndMatch ? toolCallEndMatch[0].length : 0,
        },
        {
          type: "dsml_container",
          idx: dsmlContainerStart ? dsmlContainerStart.index! : -1,
          len: dsmlContainerStart ? dsmlContainerStart[0].length : 0,
        },
        {
          type: "reply_marker",
          idx: replyMatch ? replyMatch.index! : -1,
          len: replyMatch ? replyMatch[0].length : 0,
        },
        {
          type: "think_start",
          idx: malformedThinkMatch ? malformedThinkMatch.index! : -1,
          len: malformedThinkMatch ? malformedThinkMatch[0].length : 0,
        },
      ]
        .filter((tag) => tag.idx !== -1)
        .sort((a, b) => a.idx - b.idx)

      if (indices.length === 0) {
        if (this.tagBuffer && this.currentMode !== "tool_call") {
          if (this.currentMode === "thinking") {
            this.emitThinking(this.tagBuffer)
          } else {
            this.emitText(this.tagBuffer)
          }
          this.tagBuffer = ""
        }
        return
      }

      const first = indices[0]
      const before = this.tagBuffer.slice(0, first.idx)

      if (before) {
        if (this.currentMode === "thinking") {
          this.emitThinking(before)
        } else if (this.currentMode === "tool_call") {
          const cdataMatch = before.match(
            /<!\[CDATA\[([\s\S]*?)\]\]>/i,
          )
          const argsText = cdataMatch ? cdataMatch[1] : before
          this.currentToolArgs += argsText
          this.emitToolCallDelta(before)
        } else {
          this.emitText(before)
        }
      }

      if (first.type === "think_start") {
        this.currentMode = "thinking"
      } else if (first.type === "think_end") {
        this.currentMode = "text"
      } else if (first.type === "tool_call_start") {
        this.currentMode = "tool_call"
        this.currentToolName = first.name!
        this.currentToolId = first.id || ""
        this.currentToolArgs = ""
        this.events.push({
          type: "tool_call_start",
          id: this.currentToolId,
          name: this.currentToolName,
        })
      } else if (first.type === "tool_call_end") {
        let parsedArgs: Record<string, unknown> = {}
        try {
          parsedArgs = this.parseToolArgs(this.currentToolArgs)
        } catch {}
        this.events.push({
          type: "tool_call_end",
          id: this.currentToolId,
          name: this.currentToolName,
          arguments: parsedArgs,
        })
        this.currentMode = "text"
        this.currentToolArgs = ""
      } else if (
        first.type === "final_start" ||
        first.type === "final_end" ||
        first.type === "reply_marker" ||
        first.type === "dsml_container"
      ) {
        if (first.type !== "dsml_container") this.currentMode = "text"
      }

      this.tagBuffer = this.tagBuffer.slice(first.idx + first.len)
    }
  }

  flush() {
    if (this.tagBuffer) {
      if (this.currentMode === "thinking") {
        this.emitThinking(this.tagBuffer)
      } else if (this.currentMode === "tool_call") {
        const cdataMatch = this.tagBuffer.match(
          /<!\[CDATA\[([\s\S]*?)\]\]>/i,
        )
        const argsText = cdataMatch ? cdataMatch[1] : this.tagBuffer
        this.currentToolArgs += argsText
        this.emitToolCallDelta(this.tagBuffer)
        let args: Record<string, unknown> = {}
        try {
          args = this.parseToolArgs(this.currentToolArgs)
        } catch {}
        this.events.push({
          type: "tool_call_end",
          id: this.currentToolId,
          name: this.currentToolName,
          arguments: args,
        })
      } else {
        this.emitText(this.tagBuffer)
      }
      this.tagBuffer = ""
    }
    this.events.push({ type: "end" })
  }

  private *flushEvents(): Generator<ParseEvent> {
    while (this.events.length > 0) {
      yield this.events.shift()!
    }
  }
}
